class LauncherNativeTests(unittest.TestCase):
    def setUp(self):
        self.temp=tempfile.TemporaryDirectory(); self.root=Path(self.temp.name); self.old=os.environ.get("MATH_RESEARCH_CONTROL_HOME"); control=self.root/"control"; control.mkdir(mode=0o700); os.chmod(control,0o700); os.environ["MATH_RESEARCH_CONTROL_HOME"]=str(control)
